      const NOTIFY_SW_SYNC_TAG = "uni-notif-sync";
      const NOTIFY_SW_PERIODIC_TAG = "uni-notif-periodic";
      const NOTIFY_SW_PERIODIC_MIN_INTERVAL_MS = 15 * 60 * 1000;
      const HANDOUT_INLINE_FILE_BYTES = 2 * 1024 * 1024;
      const HANDOUT_MAX_FILE_BYTES = 64 * 1024 * 1024;
      const HANDOUT_MAX_DATAURL_LEN = 3000000;
