      const CLOUD_SYNC_STABLE_AUTO_INTERVAL_HIDDEN_MS = 8 * 60 * 1000;
      const CLOUD_SYNC_STABLE_AUTO_MIN_GAP_VISIBLE_MS = 2 * 60 * 1000;
      const CLOUD_SYNC_STABLE_AUTO_MIN_GAP_HIDDEN_MS = 4 * 60 * 1000;
      const CLOUD_SYNC_STABLE_DEBOUNCE_DEFAULT_MS = 12000;
      const CLOUD_SYNC_STABLE_DEBOUNCE_SEARCH_MS = 30000;
      const CLOUD_SYNC_STABLE_DEBOUNCE_UI_MS = 8000;
